def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = sum(1 for a, b in history if b == 'C')
    opp_d = n - opp_c
    opp_coop_rate = opp_c / n

    my_d = sum(1 for a, b in history if a == 'D')

    recent = history[-10:] if n >= 10 else history
    recent_my_d = sum(1 for a, b in recent if a == 'D')

    after_my_D_C = 0
    after_my_D_D = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'C':
                after_my_D_C += 1
            else:
                after_my_D_D += 1
    retaliated = after_my_D_D > 0

    if n >= 95:
        if opp_d == 0:
            return 'D'
        if opp_coop_rate > 0.8 and not retaliated:
            return 'D'
        return 'C'

    if opp_coop_rate < 0.3:
        return 'D'

    if history[-1][1] == 'D':
        if history[-1][0] == 'C':
            recent_my_d_3 = sum(1 for a, b in history[-3:] if a == 'D') if n >= 3 else 0
            if recent_my_d_3 > 0:
                return 'C'
            return 'D'
        else:
            if opp_coop_rate > 0.5:
                if rng.random() < 0.5:
                    return 'C'
            return 'D'

    if my_d == 0:
        if n >= 10 and n % 10 == 0 and opp_coop_rate > 0.85:
            return 'D'
        return 'C'

    if my_d == 1 and history[-1][0] == 'D':
        return 'C'

    if not retaliated:
        if recent_my_d >= 8:
            return 'C'
        if rng.random() < 0.95:
            return 'D'
        return 'C'
    else:
        return 'C'
